-- user_version 2
CREATE TABLE "assets" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "content_hash" TEXT NOT NULL, "byte_size" INTEGER NOT NULL, "ext" TEXT NOT NULL DEFAULT '', "kind" TEXT NOT NULL DEFAULT 'audio', "local_rel_path" TEXT NULL, "record_sync_state" TEXT NOT NULL DEFAULT 'localOnly', "bytes_sync_state" TEXT NOT NULL DEFAULT 'localOnly', "remote_ref" TEXT NULL, PRIMARY KEY ("id"), CHECK (byte_size >= 0));
CREATE TABLE "practices" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "title" TEXT NOT NULL DEFAULT '', "timeline_duration_ms" INTEGER NOT NULL DEFAULT 0, "master_volume" REAL NOT NULL DEFAULT 1.0, "active_interpretation_id" TEXT NULL, "separation_asset_id" TEXT NULL REFERENCES assets (id), "reverb_json" TEXT NULL, "lyrics_json" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "interpretations" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "practice_id" TEXT NOT NULL REFERENCES practices (id), "name" TEXT NOT NULL DEFAULT '', "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "fx_buses" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "practice_id" TEXT NOT NULL REFERENCES practices (id), "name" TEXT NOT NULL DEFAULT '', "color_value" INTEGER NULL, "volume" REAL NOT NULL DEFAULT 1.0, "pan" REAL NOT NULL DEFAULT 0.0, "muted" INTEGER NOT NULL DEFAULT 0 CHECK ("muted" IN (0, 1)), "soloed" INTEGER NOT NULL DEFAULT 0 CHECK ("soloed" IN (0, 1)), "output_bus_id" TEXT NULL, "fx_json" TEXT NULL, "sends_json" TEXT NULL, "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "tracks" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "practice_id" TEXT NOT NULL REFERENCES practices (id), "kind" TEXT NOT NULL, "interpretation_id" TEXT NULL REFERENCES interpretations (id), "display_name" TEXT NOT NULL DEFAULT '', "color_value" INTEGER NULL, "muted" INTEGER NOT NULL DEFAULT 0 CHECK ("muted" IN (0, 1)), "soloed" INTEGER NOT NULL DEFAULT 0 CHECK ("soloed" IN (0, 1)), "volume" REAL NOT NULL DEFAULT 1.0, "pan" REAL NOT NULL DEFAULT 0.0, "bus_id" TEXT NULL REFERENCES fx_buses (id), "fx_json" TEXT NULL, "sends_json" TEXT NULL, "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CHECK (kind IN ('vocal', 'accompaniment', 'reference')));
CREATE TABLE "clips" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "track_id" TEXT NOT NULL REFERENCES tracks (id), "asset_id" TEXT NOT NULL REFERENCES assets (id), "start_ms" INTEGER NOT NULL DEFAULT 0, "duration_ms" INTEGER NOT NULL DEFAULT 0, "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CHECK (duration_ms >= 0));
CREATE TABLE "practice_notes" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "track_id" TEXT NOT NULL REFERENCES tracks (id), "position_ms" INTEGER NOT NULL DEFAULT 0, "end_ms" INTEGER NULL, "content" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("id"), CHECK (end_ms IS NULL OR end_ms > position_ms));
CREATE TABLE "technique_markers" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "track_id" TEXT NOT NULL REFERENCES tracks (id), "position_ms" INTEGER NOT NULL DEFAULT 0, "end_ms" INTEGER NULL, "technique_id" TEXT NOT NULL, "technique_name_snapshot" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK (end_ms IS NULL OR end_ms > position_ms), CHECK (technique_name_snapshot <> ''));
CREATE TABLE "techniques" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "name" TEXT NOT NULL DEFAULT '', "aliases_json" TEXT NULL, "tags_json" TEXT NULL, "summary" TEXT NOT NULL DEFAULT '', "description" TEXT NOT NULL DEFAULT '', "cues" TEXT NOT NULL DEFAULT '', "exercises" TEXT NOT NULL DEFAULT '', "acoustic_signature" TEXT NOT NULL DEFAULT '', "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "technique_media" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "hlc_wall" INTEGER NOT NULL, "hlc_ctr" INTEGER NOT NULL, "hlc_node" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL DEFAULT 1, "technique_id" TEXT NOT NULL REFERENCES techniques (id), "asset_id" TEXT NOT NULL REFERENCES assets (id), "kind" TEXT NOT NULL DEFAULT 'audio', "label" TEXT NOT NULL DEFAULT '', "order_index" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "oplog" ("seq" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entity_table" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "op" TEXT NOT NULL, "hlc_packed" TEXT NOT NULL, "payload_hash" TEXT NOT NULL, "synced" INTEGER NOT NULL DEFAULT 0 CHECK ("synced" IN (0, 1)), "depends_on_asset_id" TEXT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE "recordings_inflight" ("id" TEXT NOT NULL, "practice_id" TEXT NOT NULL, "pid" INTEGER NOT NULL, "started_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "waveform_cache" ("content_hash" TEXT NOT NULL, "algo_version" INTEGER NOT NULL, "peaks" BLOB NOT NULL, PRIMARY KEY ("content_hash", "algo_version"));
CREATE TABLE "sync_state" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "sync_quarantine" ("tbl" TEXT NOT NULL, "id" TEXT NOT NULL, "remote_hlc_packed" TEXT NOT NULL, "schema_v" INTEGER NOT NULL, "payload" TEXT NOT NULL, "reason" TEXT NOT NULL, "quarantined_at" INTEGER NOT NULL, PRIMARY KEY ("tbl", "id"));
CREATE TABLE "asset_sync" ("hash" TEXT NOT NULL, "uploaded_at" INTEGER NOT NULL, PRIMARY KEY ("hash"));
CREATE UNIQUE INDEX ux_track_slot ON tracks (practice_id, kind) WHERE deleted_at IS NULL AND kind IN ('accompaniment', 'reference');
CREATE INDEX ix_assets_hash ON assets (content_hash);
CREATE INDEX ix_practices_updated ON practices (deleted_at, updated_at);
CREATE INDEX ix_interp_practice ON interpretations (practice_id);
CREATE INDEX ix_tracks_practice ON tracks (practice_id);
CREATE INDEX ix_clips_track ON clips (track_id);
CREATE INDEX ix_notes_track ON practice_notes (track_id);
CREATE INDEX ix_markers_track ON technique_markers (track_id);
CREATE INDEX ix_markers_technique ON technique_markers (technique_id);
CREATE INDEX ix_buses_practice ON fx_buses (practice_id);
CREATE INDEX ix_media_technique ON technique_media (technique_id);
CREATE INDEX ix_oplog_unsynced ON oplog (synced, seq);
CREATE INDEX ix_oplog_hlc ON oplog (hlc_packed);
CREATE INDEX ix_assets_rel ON assets (local_rel_path);
CREATE INDEX ix_oplog_entity ON oplog (entity_table, entity_id, seq);
